SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;DECLARE @i int=0;WHILE @i<30000 BEGIN INSERT lab.LogLoad(Payload) VALUES(REPLICATE(CONVERT(varchar(36),NEWID()),110));SET @i+=1;END;COMMIT;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;THROW;END CATCH;CHECKPOINT;INSERT lab.Evidence SELECT 'SMALL_GROWTH',(SELECT COUNT(*) FROM sys.dm_db_log_info(DB_ID())),size*8.0/1024,growth*8.0/1024 FROM sys.database_files WHERE type=1;PRINT 'SQLPERF_SUMMARY|PASS|OK';
